// The wasm32 file, picked by `nish-wasm32` in a wasm32 build ahead of
// `nish-i32`. It exports the same `seed` with the same signature as
// `./native.ts`, which both builds check (NL3063), and reaches no host. Its
// value is one no other file returns, so a native build that picked it by
// mistake would exit 107, not 7.
export const seed = (): i32 => 200;
